from typing import List
import heapq


def findMedianSortedArrays(nums1: List[int], nums2: List[int]) -> float:
    """
    Find median of two sorted arrays in O(log(min(m, n))) time.
    """
    # Ensure nums1 is the smaller array
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    m, n = len(nums1), len(nums2)
    if m == 0:
        # median of nums2 directly
        mid = n // 2
        if n % 2 == 1:
            return float(nums2[mid])
        else:
            return (nums2[mid - 1] + nums2[mid]) / 2.0

    low, high = 0, m
    half_len = (m + n + 1) // 2

    while low <= high:
        i = (low + high) // 2  # partition in nums1
        j = half_len - i       # partition in nums2

        max_left_x = float("-inf") if i == 0 else nums1[i - 1]
        min_right_x = float("inf") if i == m else nums1[i]

        max_left_y = float("-inf") if j == 0 else nums2[j - 1]
        min_right_y = float("inf") if j == n else nums2[j]

        if max_left_x <= min_right_y and max_left_y <= min_right_x:
            # Correct partition
            if (m + n) % 2 == 1:
                return float(max(max_left_x, max_left_y))
            else:
                return (max(max_left_x, max_left_y) + min(min_right_x, min_right_y)) / 2.0
        elif max_left_x > min_right_y:
            # move partition in nums1 to left
            high = i - 1
        else:
            # move partition in nums1 to right
            low = i + 1

    # Should never reach here if input constraints guarantee at least one array non-empty
    raise ValueError("Could not find median partitions")


class StreamingMedian:
    """
    Streaming median supporting:
    - add(num): O(log n)
    - median(): O(1)

    Uses two heaps:
    - lower: max-heap (implemented via negatives)
    - higher: min-heap
    """

    def __init__(self) -> None:
        self.lower: List[int] = []   # max-heap via negatives
        self.higher: List[int] = []  # min-heap

    def add(self, num: int) -> None:
        # Decide which heap to push to
        if not self.lower or num <= -self.lower[0]:
            heapq.heappush(self.lower, -num)
        else:
            heapq.heappush(self.higher, num)

        # Rebalance heaps to ensure size difference <= 1
        if len(self.lower) > len(self.higher) + 1:
            val = -heapq.heappop(self.lower)
            heapq.heappush(self.higher, val)
        elif len(self.higher) > len(self.lower) + 1:
            val = heapq.heappop(self.higher)
            heapq.heappush(self.lower, -val)

    def median(self) -> float:
        if not self.lower and not self.higher:
            raise ValueError("No elements present")
        if len(self.lower) == len(self.higher):
            # even count
            return (-self.lower[0] + self.higher[0]) / 2.0
        elif len(self.lower) > len(self.higher):
            return float(-self.lower[0])
        else:
            return float(self.higher[0])


